<script setup>
import { computed, reactive, ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MDialog from '../../../components/mds/MDialog.vue'; import MInput from '../../../components/mds/MInput.vue'; import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { toAwardDraft,toAwardPayload } from '../domain/award-write.mjs';
const props=defineProps({record:{type:Object,default:()=>({})},editing:Boolean,saving:Boolean,error:String,safeAreaStyle:Object});const emit=defineEmits(['cancel','save']);const draft=reactive({ ...toAwardDraft(props.record) });const localError=ref('');const discard=ref(false);const title=computed(()=>props.editing?'Sửa giải thưởng':'Thêm giải thưởng');const showCost=computed(()=>!props.editing||Object.hasOwn(props.record,'cost'));const types=['gov','association','other'].map(value=>({value,label:value==='gov'?'Cơ quan nhà nước':value==='association'?'Hiệp hội':'Khác'}));const statuses=['','Đang mở','Đã đóng','Đã hoàn tất'].map(value=>({value,label:value||'Chọn trạng thái'}));watch(()=>props.record,record=>Object.assign(draft,toAwardDraft(record)),{deep:true});function submit(){try{localError.value='';emit('save',toAwardPayload(draft,{existingRecord:props.editing?props.record:null}));}catch(error){localError.value=error.message;}}
</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar :title="title" @back="discard=true"><template #actions><MButton variant="link" :disabled="saving" @click="discard=true">Hủy</MButton></template></MMobileTopBar><form class="flex min-h-0 flex-1 flex-col" @submit.prevent="submit"><div class="min-h-0 flex-1 overflow-y-auto"><div class="mds-mobile-gutter-x space-y-4 py-4"><label><span class="mb-1 block text-[13px] font-medium">Tên giải thưởng *</span><MInput v-model="draft.name" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Đơn vị tổ chức</span><MInput v-model="draft.organizer" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Loại đơn vị</span><MSelect v-model="draft.organizer_type" :options="types" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Hạn nộp</span><MInput v-model="draft.submission_deadline" type="date" :disabled="saving"/></label><label v-if="showCost"><span class="mb-1 block text-[13px] font-medium">Chi phí tham gia (đ)</span><MInput v-model="draft.cost" type="number" min="0" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Phạm vi</span><MInput v-model="draft.scope" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Trạng thái</span><MSelect v-model="draft.status" :options="statuses" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Điều kiện</span><MTextarea v-model="draft.eligibility" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Tiêu chí</span><MTextarea v-model="draft.criteria" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Hồ sơ cần thiết</span><MTextarea v-model="draft.required_docs" :disabled="saving"/></label><label><span class="mb-1 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :disabled="saving"/></label><p v-if="error||localError" role="alert" class="rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{error||localError}}</p></div></div><footer class="shrink-0 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-4 pb-[calc(12px+var(--mds-mobile-safe-bottom))] pt-3"><MButton variant="primary" class="w-full" :loading="saving" :disabled="saving" @click="submit">Lưu giải thưởng</MButton></footer></form><MDialog v-model="discard" title="Bỏ thay đổi?" type="danger" confirm-text="Bỏ thay đổi" @confirm="emit('cancel')"><p>Thông tin chưa lưu sẽ không được giữ lại.</p></MDialog></section></template>
